// ============================================================
// PARSER CEGOS — extrait scores + verbatim d'un PDF Cegos
// ============================================================

const text = $input.item.json.text || '';
const fileName = $('Google Drive — Nouveau PDF').item.json.name || '';

// --- Helpers ---
function extractScore(text, pattern) {
  const match = text.match(pattern);
  if (!match) return null;
  return parseFloat(match[1].replace(',', '.'));
}

function extractText(text, pattern) {
  const match = text.match(pattern);
  return match ? match[1].trim() : '';
}

// --- Nom du client ---
// Le nom de fichier Cegos suit souvent le pattern Survey-XXXXXX.pdf
// Le nom de la formation/client est en début de document
let clientName = '';
const clientPatterns = [
  /(?:Entreprise|Société|Client|Organisme|Établissement)[\s:]+([^\n]+)/i,
  /^([A-Z][^\n]{3,50})\n/m
];
for (const p of clientPatterns) {
  const m = text.match(p);
  if (m) { clientName = m[1].trim(); break; }
}
if (!clientName) clientName = fileName.replace('.pdf','').replace(/Survey-\d+/, '').trim() || 'À compléter';

// --- Date ---
let sessionDate = '';
const dateMatch = text.match(/(\d{2}[\/\-]\d{2}[\/\-]\d{4})/);
if (dateMatch) {
  const parts = dateMatch[1].split(/[\/\-]/);
  if (parts[2].length === 4) {
    sessionDate = `${parts[2]}-${parts[1].padStart(2,'0')}-${parts[0].padStart(2,'0')}`;
  }
}

// --- Scores /100 ---
// Structure Cegos : critères notés sur 4 → ×25 pour obtenir /100
// Les critères varient selon le questionnaire ; on cherche par libellé

const scorePatterns = {
  utilite:    /(?:Utilité|Utilite|utilité globale|répondu à vos attentes)[^\d]*(\d+[,.]?\d*)/i,
  expertise:  /(?:Expertise|Compétence|compétences du formateur|expertise)[^\d]*(\d+[,.]?\d*)/i,
  echanges:   /(?:[Éé]changes|Interactions|échanges entre participants)[^\d]*(\d+[,.]?\d*)/i,
  variete:    /(?:[Vv]ariété|Diversité|variété des activités)[^\d]*(\d+[,.]?\d*)/i,
  objectifs:  /(?:objectifs|Objectifs personnels)[^\d]*(\d+[,.]?\d*)/i,
};

// Cherche aussi le format « X,XX/100 » ou « X/4 »
const scores = {};
for (const [key, pattern] of Object.entries(scorePatterns)) {
  let val = extractScore(text, pattern);
  if (val !== null) {
    // Si la valeur est sur 4, convertir en /100
    if (val <= 4) val = Math.round(val * 25);
    scores[key] = val;
  } else {
    scores[key] = null;
  }
}

// Score moyen (utilité globale par défaut, ou moyenne des scores non-null)
const nonNullScores = Object.values(scores).filter(v => v !== null);
const scoreMoyen = nonNullScores.length > 0
  ? Math.round(nonNullScores.reduce((a,b)=>a+b,0) / nonNullScores.length)
  : null;

// Utiliser l'utilité si dispo, sinon la moyenne
const scoreUtilite = scores.utilite ?? scoreMoyen;

// --- Verbatim ---
const verbatimPatterns = [
  /(?:Points forts|Ce que vous avez aimé|Ce qui vous a aidé)[^\n]*\n([\s\S]{20,500}?)(?:\n\n|Points à améliorer|$)/i,
  /(?:Commentaires?|Remarques?|Suggestions?)[^\n]*\n([\s\S]{20,500}?)(?:\n\n|$)/i,
];
let verbatim = '';
for (const p of verbatimPatterns) {
  const m = text.match(p);
  if (m) { verbatim = m[1].trim(); break; }
}

// --- Stagiaires et répondants ---
// Approximation : 1 répondant détecté par ce fichier
const stagiaires = 1; // sera agrégé dans kpis.json
const repondants = 1;

// --- Type (INTRA ou INTER) ---
const typeMatch = text.match(/\b(INTRA|INTER)\b/i);
const sessionType = typeMatch ? typeMatch[1].toUpperCase() : 'INTRA';

// --- Note globale Notion (arrondie sur 5) ---
let noteNotion = 'Non noté';
if (scoreUtilite !== null) {
  const note = Math.ceil(scoreUtilite / 20); // 100/20 = 5 paliers
  noteNotion = String(Math.min(5, Math.max(1, note)));
}

// --- Output ---
return {
  clientName,
  sessionDate,
  sessionType,
  scores,
  scoreUtilite,
  scoreMoyen,
  verbatim,
  noteNotion,
  stagiaires,
  repondants,
  fileName,
  textLength: text.length,
  rawTextPreview: text.substring(0, 300),
};

// Récupère kpis.json depuis GitHub (base64) et ajoute la nouvelle session

const githubResponse = $('GitHub — Lire kpis.json').item.json;
const parsed = $('Parser scores Cegos').item.json;

// Décoder le contenu base64
const decoded = Buffer.from(githubResponse.content.replace(/\n/g,''), 'base64').toString('utf-8');
const kpis = JSON.parse(decoded);

// Ajouter la nouvelle session dans sessions_detail
const newSession = {
  client: parsed.clientName,
  date: parsed.sessionDate || new Date().toISOString().split('T')[0],
  type: parsed.sessionType,
  stagiaires: 1,
  repondants: 1,
  score_utilite:   parsed.scores.utilite   ?? 0,
  score_expertise: parsed.scores.expertise ?? 0,
  score_echanges:  parsed.scores.echanges  ?? 0,
  score_variete:   parsed.scores.variete   ?? 0,
  score_objectifs: parsed.scores.objectifs ?? 0,
};

kpis.cegos.sessions_detail.push(newSession);

// Recalculer les agrégats à partir de sessions_detail
const all = kpis.cegos.sessions_detail;
kpis.cegos.sessions    = all.length;
kpis.cegos.stagiaires  = all.reduce((s, d) => s + (d.stagiaires || 0), 0);
kpis.cegos.repondants  = all.reduce((s, d) => s + (d.repondants || 0), 0);

const avg = (field) => {
  const valid = all.filter(d => d[field] != null && d[field] > 0);
  if (!valid.length) return 0;
  return Math.round((valid.reduce((s,d) => s + d[field], 0) / valid.length) * 10) / 10;
};

kpis.cegos.score_utilite_moyen = avg('score_utilite');
kpis.cegos.score_expertise     = avg('score_expertise');
kpis.cegos.score_echanges      = avg('score_echanges');
kpis.cegos.score_variete       = avg('score_variete');
kpis.cegos.score_objectifs     = avg('score_objectifs');

// Mise à jour date
kpis._mise_a_jour = new Date().toISOString().split('T')[0];

// Encoder en base64 pour l'API GitHub
const updatedContent = Buffer.from(JSON.stringify(kpis, null, 2) + '\n').toString('base64');

return {
  updatedKpisJson: JSON.stringify(kpis, null, 2),
  base64Content: updatedContent,
  sha: githubResponse.sha,
  commitMessage: `kpis: +1 session ${parsed.clientName} (${parsed.sessionDate}) — ${kpis.cegos.sessions} sessions au total`,
};
